import {useEffect,useMemo,useState} from 'react';
import {Link} from 'react-router-dom';
import {
  AlertCircle,ArrowRight,Ban,Bell,BellRing,BrainCircuit,CalendarDays,Check,
  CheckCircle2,ChevronRight,Clock3,Download,Edit3,FileBarChart,FileText,
  Gauge,IndianRupee,Info,Lightbulb,LoaderCircle,LockKeyhole,
  MessageSquareText,Moon,Plus,Receipt,RefreshCw,Search,ShieldCheck,Sparkles,
  Tags,Trash2,Upload,WalletCards,X,Zap
} from 'lucide-react';
import api,{message} from './api';
import './advanced.css';

const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(value)||0);
const pretty=value=>String(value||'').replaceAll('_',' ').toLowerCase().replace(/\b\w/g,char=>char.toUpperCase());
const displayDate=value=>value?new Date(`${value}`.length===10?`${value}T00:00:00`:value).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not set';
const asList=(data,key)=>Array.isArray(data)?data:Array.isArray(data?.[key])?data[key]:Array.isArray(data?.content)?data.content:[];
const todayMonth=()=>new Date().toISOString().slice(0,7);

function FeatureHeading({eyebrow,title,copy,action}){
  return <div className="advanced-heading"><div><span>{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{action}</div>;
}

function StatusMessage({value,onClose}){
  if(!value)return null;
  return <div className={`advanced-toast ${value.type||'success'}`} role="status"><span>{value.type==='error'?<AlertCircle/>:<CheckCircle2/>}{value.text}</span>{onClose&&<button aria-label="Dismiss" onClick={onClose}><X/></button>}</div>;
}

function PageLoader({label='Loading your workspace...'}){
  return <div className="advanced-loader"><LoaderCircle/><span>{label}</span></div>;
}

function FeatureEmpty({icon:Icon=Sparkles,title,copy,action}){
  return <div className="advanced-empty"><div><Icon/></div><h3>{title}</h3><p>{copy}</p>{action}</div>;
}

function Toggle({checked,onChange,label}){
  return <button type="button" className={`advanced-switch ${checked?'on':''}`} role="switch" aria-checked={checked} aria-label={label} onClick={onChange}><i/><span>{checked?'On':'Off'}</span></button>;
}

const ruleTypes=[
  ['WAITING_PERIOD','Cooling-off period','Pause a purchase for a set number of days.',Clock3],
  ['MAX_PRICE','Price boundary','Flag purchases above an amount you choose.',IndianRupee],
  ['EMOTION_BLOCK','Emotion guard','Block decisions during a vulnerable mood.',BrainCircuit],
  ['LATE_NIGHT','Late-night lock','Protect a time window when impulse control is lower.',Moon],
  ['REQUIRE_COMPARISON','Comparison required','Require alternatives before a costly purchase.',Search],
  ['CUSTOM','Personal promise','Create a flexible rule in your own words.',Sparkles]
];
const categories=['ALL','ELECTRONICS','CLOTHING','FOOD','BEAUTY','ENTERTAINMENT','HOME','TRAVEL','GAMING','ACCESSORIES','OTHER'];
const emotions=['NORMAL','HAPPY','EXCITED','BORED','STRESSED','SAD','FRUSTRATED'];
const blankRule={name:'',description:'',ruleType:'WAITING_PERIOD',category:'ALL',amountThreshold:'',waitDays:1,blockedEmotion:'',startHour:22,endHour:6,active:true};
const ruleIcon=type=>ruleTypes.find(item=>item[0]===type)?.[3]||ShieldCheck;
const ruleCopy=rule=>{
  if(rule.ruleType==='WAITING_PERIOD')return `${rule.waitDays||1}-day pause${rule.category&&rule.category!=='ALL'?` for ${pretty(rule.category)}`:''}`;
  if(rule.ruleType==='MAX_PRICE')return `Check purchases above ${money(rule.amountThreshold)}`;
  if(rule.ruleType==='EMOTION_BLOCK')return `Pause when feeling ${pretty(rule.blockedEmotion)}`;
  if(rule.ruleType==='LATE_NIGHT')return `Active from ${String(rule.startHour??22).padStart(2,'0')}:00 to ${String(rule.endHour??6).padStart(2,'0')}:00`;
  if(rule.ruleType==='REQUIRE_COMPARISON')return `Compare alternatives${rule.amountThreshold?` above ${money(rule.amountThreshold)}`:''}`;
  return rule.description||'A promise to your future self';
};

