  async function download(kind){setDownloading(kind);try{const html=kind==='html';const response=await api.get(html?'/reports/monthly.html':'/reports/evaluations.csv',{params:{month},responseType:'blob'});const url=URL.createObjectURL(response.data);const anchor=document.createElement('a');anchor.href=url;anchor.download=html?`mindfulcart-${month}-report.html`:`mindfulcart-${month}-evaluations.csv`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);setNotice({text:`${html?'Monthly report':'Evaluation data'} downloaded.`})}catch(error){setNotice({type:'error',text:message(error)})}finally{setDownloading('')}}
  const categories=reportEntries(report?.categoryBreakdown||report?.categories);
  const maxCategory=Math.max(1,...categories.map(([,value])=>Number(value)||0));
  return <>
    <FeatureHeading eyebrow="MONTHLY REVIEW" title="Turn reflections into a clear story" copy="See what you considered, what you chose, and where your future spending can become more intentional." action={<div className="month-control"><CalendarDays/><input aria-label="Report month" type="month" max={todayMonth()} value={month} onChange={event=>setMonth(event.target.value)}/></div>}/>
    <StatusMessage value={notice} onClose={()=>setNotice(null)}/>
    <div className="report-actions"><div><FileBarChart/><span><b>Export your data</b><small>Useful for your own review or project demonstration.</small></span></div><button className="secondary" disabled={!!downloading} onClick={()=>download('csv')}><Download/> {downloading==='csv'?'Preparing...':'Evaluation CSV'}</button><button className="primary" disabled={!!downloading} onClick={()=>download('html')}><FileText/> {downloading==='html'?'Preparing...':'Monthly report'}</button></div>
    {loading?<PageLoader label="Building your monthly story..."/>:report?<><section className="report-cover"><div><span><Sparkles/> MINDFUL MONTH IN REVIEW</span><h2>{report.headline||report.summaryHeadline||'A month of more deliberate decisions'}</h2><p>{report.summary||report.insight||report.narrative||'Each evaluation is a moment where you created space between wanting and choosing.'}</p></div><div className="report-month"><small>REPORTING PERIOD</small><strong>{new Date(`${month}-02`).toLocaleDateString('en-IN',{month:'long'})}</strong><span>{month.slice(0,4)}</span></div></section><div className="report-metrics"><section><small>EVALUATED</small><strong>{report.evaluatedCount??report.totalEvaluations??report.evaluated??0}</strong><span>purchase decisions paused</span></section><section><small>AVOIDED</small><strong>{report.avoidedCount??report.avoided??0}</strong><span>{money(report.avoidedAmount??report.moneySaved)} protected</span></section><section><small>PURCHASED</small><strong>{report.purchasedCount??report.purchased??0}</strong><span>{money(report.purchasedAmount)} confirmed spend</span></section><section><small>AVERAGE SCORE</small><strong>{Math.round(Number(report.averageImpulseScore??report.averageScore??report.avgScore)||0)}<em>/100</em></strong><span>impulse risk</span></section></div><div className="report-grid"><section className="report-panel category-report"><header><div><span className="section-kicker">WHERE ATTENTION WENT</span><h2>Category activity</h2></div><Tags/></header>{categories.length?<div className="category-bars">{categories.map(([label,value])=><div key={label}><span><b>{pretty(label)}</b><em>{typeof value==='number'?value:Number(value)||0}</em></span><i><b style={{width:`${Math.max(4,(Number(value)||0)/maxCategory*100)}%`}}/></i></div>)}</div>:<FeatureEmpty icon={Tags} title="No category activity" copy="Complete evaluations this month to reveal your spending attention."/>}</section><section className="report-panel report-patterns"><span className="section-kicker">PATTERN SNAPSHOT</span><h2>What shaped decisions</h2><div><span><BrainCircuit/></span><p><small>MOST COMMON TRIGGER</small><b>{pretty(report.topTrigger||report.commonTrigger)||'No pattern yet'}</b></p></div><div><span><Tags/></span><p><small>TOP CATEGORY</small><b>{pretty(report.topCategory)||'No pattern yet'}</b></p></div><div><span><Clock3/></span><p><small>STILL COOLING OFF</small><b>{report.waitingCount??report.waiting??0} purchase decisions</b></p></div></section></div><section className="report-reflection"><div><Lightbulb/></div><span><small>COACHING REFLECTION</small><h2>{report.recommendationTitle||'One change to carry forward'}</h2><p>{report.recommendation||report.coachingTip||report.insights?.[0]||'Choose one personal rule for your most common trigger and test it during your next purchase evaluation.'}</p></span><Link to="/rules">Create a boundary <ArrowRight/></Link></section></>:<FeatureEmpty icon={FileBarChart} title="No report is available" copy="Complete a purchase evaluation, then return here for your monthly review." action={<Link className="primary" to="/evaluate">Evaluate a purchase</Link>}/>} 
  </>;
}

const samplePrompts=[
  'I found Sony headphones for Rs 8,000 on Instagram at 30% off.',
  'Thinking about a Rs 2,499 jacket because the sale ends tonight.',
  'I am bored and want to order a gaming mouse for Rs 3,200.'
];

export function SmartCapturePage(){
  const[mode,setMode]=useState('text'),[text,setText]=useState(''),[file,setFile]=useState(null),[preview,setPreview]=useState(''),[result,setResult]=useState(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState(null);
  useEffect(()=>{if(!file){setPreview('');return undefined}const url=file.type.startsWith('image/')?URL.createObjectURL(file):'';setPreview(url);return()=>{if(url)URL.revokeObjectURL(url)}},[file]);
  async function parseText(event){event.preventDefault();if(!text.trim())return;setBusy(true);setResult(null);try{const{data}=await api.post('/tools/parse-purchase',{text:text.trim()});setResult(data)}catch(error){setNotice({type:'error',text:message(error)})}finally{setBusy(false)}}
  async function extract(event){event.preventDefault();if(!file)return;setBusy(true);setResult(null);try{const body=new FormData();body.append('file',file);if(text.trim())body.append('extractedText',text.trim());const{data}=await api.post('/tools/extract-metadata',body,{headers:{'Content-Type':'multipart/form-data'}});setResult(data?.draft?{...data.draft,extractionStatus:data.extractionStatus,ocrText:data.ocrText,ocrEngine:data.engine,ocrDurationMs:data.durationMs,ocrCharacterCount:data.ocrCharacterCount}:data);setNotice({text:'OCR finished. Review the extracted text and suggested fields.'})}catch(error){setNotice({type:'error',text:message(error)})}finally{setBusy(false)}}
  function continueToEvaluate(){const draft=result?.draft||result;if(!draft)return;sessionStorage.setItem('purchaseDraft',JSON.stringify(draft));window.location.assign('/evaluate')}
  return <>
    <FeatureHeading eyebrow="SMART CAPTURE" title="Describe it. We will structure the decision." copy="Start with natural language or a receipt screenshot, then review every extracted detail before evaluating."/>
    <StatusMessage value={notice} onClose={()=>setNotice(null)}/>
    <section className="capture-shell"><div className="capture-input"><div className="capture-tabs"><button className={mode==='text'?'active':''} onClick={()=>{setMode('text');setResult(null)}}><MessageSquareText/> Describe a purchase</button><button className={mode==='receipt'?'active':''} onClick={()=>{setMode('receipt');setResult(null)}}><Receipt/> Receipt or screenshot</button></div>{mode==='text'?<form onSubmit={parseText}><div className="capture-prompt"><Sparkles/><textarea autoFocus placeholder="Try: I saw a smartwatch for Rs 6,999 in an Instagram ad. It is 40% off and the deal ends tonight..." value={text} onChange={event=>setText(event.target.value)}/><span>{text.length}/1000</span></div><div className="example-prompts"><small>TRY AN EXAMPLE</small>{samplePrompts.map(value=><button type="button" onClick={()=>setText(value)} key={value}>{value}<ChevronRight/></button>)}</div><button className="primary capture-submit" disabled={busy||!text.trim()}>{busy?<><LoaderCircle className="spin"/> Understanding purchase...</>:<>Extract purchase details <ArrowRight/></>}</button></form>:<form onSubmit={extract}><label className={`upload-zone ${file?'has-file':''}`}><input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" onChange={event=>{const selected=event.target.files?.[0];if(selected&&selected.size>8*1024*1024){setNotice({type:'error',text:'Choose a file smaller than 8 MB.'});return}setFile(selected||null)}}/>{preview?<img src={preview} alt="Selected receipt preview"/>:<div>{file?<FileText/>:<Upload/>}<h3>{file?file.name:'Drop a receipt or shopping screenshot'}</h3><p>{file?`${(file.size/1024/1024).toFixed(1)} MB · Click to replace`:'PNG, JPG, WEBP, or PDF · Up to 8 MB'}</p></div>}</label><label className="optional-text">Visible text <span>optional, improves accuracy</span><textarea placeholder="Paste the receipt or screenshot text if you have it..." value={text} onChange={event=>setText(event.target.value)}/></label><button className="primary capture-submit" disabled={busy||!file}>{busy?<><LoaderCircle className="spin"/> Reading file...</>:<>Extract purchase details <ArrowRight/></>}</button><p className="privacy-copy"><LockKeyhole/> Your upload is used only to extract purchase details for this decision.</p></form>}</div><aside className="capture-preview"><header><span><BrainCircuit/> STRUCTURED DRAFT</span>{result?.confidence!=null&&<em>{Math.round(Number(result.confidence)*(Number(result.confidence)<=1?100:1))}% confidence</em>}</header>{result?<div className="extraction-result"><div className="extracted-product"><div>{result.productName?.[0]||'?'}</div><span><small>PRODUCT</small><h2>{result.productName||'Review product name'}</h2><p>{pretty(result.category)||'Category not detected'}</p></span></div><div className="extracted-fields"><div><small>PRICE</small><b>{result.price!=null?money(result.price):'Not detected'}</b></div><div><small>DISCOUNT</small><b>{result.discountPercentage!=null?`${result.discountPercentage}%`:'Not detected'}</b></div><div><small>SOURCE</small><b>{pretty(result.sourceOfInterest)||'Not detected'}</b></div><div><small>MOOD</small><b>{pretty(result.emotionalState)||'Not detected'}</b></div></div>{result.detectedFields?.length>0&&<div className="detected-list"><small>DETECTED SIGNALS</small>{result.detectedFields.map(field=><span key={field}><Check/> {pretty(field)}</span>)}</div>}{result.warnings?.length>0&&<div className="extraction-warnings">{result.warnings.map(warning=><span key={warning}><AlertCircle/>{warning}</span>)}</div>}<button className="primary continue-evaluation" onClick={continueToEvaluate}>Review in purchase evaluation <ArrowRight/></button><small className="review-reminder">Always confirm extracted details before saving.</small></div>:<div className="capture-placeholder"><div><Receipt/></div><h3>Your draft will appear here</h3><p>We will identify price, discount, category, source, and emotional cues when possible.</p><ul><li><Check/> You stay in control of every field</li><li><Check/> Uncertain details are clearly marked</li><li><Check/> Nothing is purchased automatically</li></ul></div>}</aside></section>
    {result?.extractionStatus&&<section className="ocr-proof"><div><CheckCircle2/><span><small>{result.extractionStatus==='OCR_COMPLETE'?'OCR COMPLETE':'TEXT EXTRACTED'}</small><b>{result.ocrEngine}</b></span><em>{result.ocrCharacterCount||0} characters · {result.ocrDurationMs||0} ms</em></div>{result.ocrText&&<details><summary>View recognized text</summary><pre>{result.ocrText}</pre></details>}</section>}
  </>;
}
